import * as React from 'react';
import { Slot, Slottable } from '@radix-ui/react-slot';
import { tv, type VariantProps } from 'tailwind-variants';
import { cn } from '@/lib/utils';
import { Loader2 } from 'lucide-react';

const buttonVariants = tv({
  slots: {
    base: "inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  },
  variants: {
    /** 变体 */
    variant: {
      null: '',
      default: 'bg-primary text-primary-foreground hover:bg-primary/90',
      outline:
        'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
      secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
      ghost: 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
      link: 'text-primary underline-offset-4 hover:underline',
      destructive:
        'bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40',
    },
    /** 尺寸 */
    size: {
      null: '',
      default: "h-9 px-4 py-2 has-[>svg]:px-3 [&_svg:not([class*='size-'])]:size-4",
      sm: 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
      lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
      icon: 'size-9',
      'icon-sm': 'size-8',
      'icon-lg': 'size-10',

      '40px': 'h-10 gap-2 rounded-[12px] px-5 py-2.5 text-sm leading-normal [&_svg]:size-5',
      '46px': 'h-11.5 rounded-[10px] px-5 text-xs',
      '48px': 'h-12 rounded-[16px] px-4 text-base',
      '52px': 'h-13 rounded-[12px] text-base [&_svg]:h-auto [&_svg]:w-5.5',
      '53px': 'h-13 rounded-[16px] px-8 py-4 text-base',
      '58px': 'not-only-of-type: h-14.5 rounded-[16px] px-3 py-2 text-lg',
    },
    /** 颜色 */
    color: {
      null: '',
      default: '',

      '#062936':
        'bg-(--color-bg) text-(--color-text) outline-4 outline-[#F6FDFE] outline-solid [--color-bg-active:#062936] [--color-bg-hover:#062936cc] [--color-bg:#062936] [--color-text:#F1F9FF] hover:bg-(--color-bg-hover) active:bg-(--color-bg-active)',
      '#DEEAEF':
        'bg-(--color-bg) text-(--color-text) [--color-bg-active:#DEEAEF] [--color-bg-hover:#DEEAEFcc] [--color-bg:#DEEAEF] [--color-text:#0F3F6A] hover:bg-(--color-bg-hover) active:bg-(--color-bg-active)',
      '#3A8EE2-#3AB2E2':
        'bg-linear-to-r from-[#3A8EE2] to-[#3AC9E2] text-[#F1F9FF] hover:opacity-80',
      '#85A7FF-#466DFF':
        'bg-linear-to-r from-[#3B8EE2] to-[#44CCE4] text-[#F1F9FF] outline-4 outline-[#DAEEFF] outline-solid hover:opacity-80',
      '#D6FFF1-#CAEDFF':
        'bg-linear-to-r from-[#D6FFF1] to-[#CAEDFF] text-[#062936] hover:opacity-80',
      '#3A8EE2-#3AC9E2':
        'border-4 border-[#8EA3B2] bg-linear-to-r from-[#3A8EE2] to-[#3AC9E2] text-white hover:opacity-80',
    },
  },
  defaultVariants: {
    variant: 'default',
    size: 'default',
    color: 'default',
  },
});

function Button({
  asChild = false,
  children,
  className,
  variant = 'default',
  size = 'default',
  color = 'default',
  disabled = false,
  loading = false,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
    /** 是否显示为加载状态 */
    loading?: boolean;
  }) {
  const Component = asChild ? Slot : 'button';
  const slots = buttonVariants({ variant, size, color });

  return (
    <Component
      data-slot="button"
      data-variant={variant}
      data-size={size}
      data-color={color}
      className={cn(slots.base(), className)}
      disabled={disabled || loading}
      {...props}
    >
      {!loading ? null : <Loader2 className="animate-spin" />}
      <Slottable>{children}</Slottable>
    </Component>
  );
}

export { Button, buttonVariants };

import type { Meta, StoryObj } from '@storybook/nextjs';
import { Button, buttonVariants } from '../';

const meta = {
  title: 'UI 组件/Button 按钮',
  component: Button,
  argTypes: {
    variant: {
      control: { type: 'radio' },
      table: {
        defaultValue: { summary: 'default' },
      },
    },
    size: {
      control: { type: 'radio' },
      table: {
        defaultValue: { summary: 'default' },
      },
    },
    color: {
      control: { type: 'radio' },
      table: {
        defaultValue: { summary: 'default' },
      },
    },
  },
} satisfies Meta<typeof Button>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    children: '默认按钮',
  },
};

export const Variants: Story = {
  render: function (props) {
    return (
      <div className="flex flex-row gap-2">
        <Button {...props} variant="default">
          默认按钮
        </Button>
        <Button {...props} variant="secondary">
          次要按钮
        </Button>
        <Button {...props} variant="outline">
          描边按钮
        </Button>
        <Button {...props} variant="ghost">
          幽灵按钮
        </Button>
        <Button {...props} variant="link">
          链接按钮
        </Button>
        <Button {...props} variant="destructive">
          危险按钮
        </Button>
      </div>
    );
  },
};

export const Sizes: Story = {
  render: function (props) {
    return (
      <>
        <section className="flex flex-row flex-wrap gap-2">
          <Button {...props} size="sm">
            小按钮
          </Button>
          <Button {...props} size="default">
            默认按钮
          </Button>
          <Button {...props} size="lg">
            大按钮
          </Button>
          <Button {...props} size="icon-sm">
            🔍
          </Button>
          <Button {...props} size="icon">
            🔍
          </Button>
          <Button {...props} size="icon-lg">
            🔍
          </Button>
        </section>

        <section className="mt-4 flex flex-row flex-wrap gap-2">
          {(
            Object.keys(buttonVariants.variants.size)?.filter(
              (key) => !['sm', 'default', 'lg', 'icon-sm', 'icon', 'icon-lg'].includes(key),
            ) as Array<keyof typeof buttonVariants.variants.size>
          ).map((size) => (
            <Button key={size} {...props} size={size}>
              {size}
            </Button>
          ))}
        </section>
      </>
    );
  },
};

export const Colors: Story = {
  render: function (props) {
    return (
      <>
        <section className="flex flex-row flex-wrap gap-2">
          <Button {...props} color="default">
            默认颜色
          </Button>
        </section>

        <section className="mt-4 flex flex-row flex-wrap gap-2">
          {(
            Object.keys(buttonVariants.variants.color)?.filter(
              (key) => !['default'].includes(key),
            ) as Array<keyof typeof buttonVariants.variants.color>
          )?.map((color) => (
            <Button key={color} {...props} color={color}>
              {color}
            </Button>
          ))}
        </section>
      </>
    );
  },
};
